{{!-- Styling parameters: class, buttonClass, statusClass --}}
{{#with this as |ghostcnStyles|}}
<nav class="ghcn-pagination{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" role="navigation" aria-label="Pagination">
    <div class="ghcn-pagination__side">{{#if prev}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="{{page_url prev}}" rel="prev"><span aria-hidden="true">&larr;</span> Newer</a>{{/if}}</div>
    <span class="ghcn-pagination__status{{#if ghostcnStyles.statusClass}} {{ghostcnStyles.statusClass}}{{/if}}">Page <strong>{{page}}</strong> of <strong>{{pages}}</strong></span>
    <div class="ghcn-pagination__side ghcn-pagination__side--end">{{#if next}}<a class="ghcn-button{{#if ghostcnStyles.buttonClass}} {{ghostcnStyles.buttonClass}}{{/if}} ghcn-button--outline" href="{{page_url next}}" rel="next">Older <span aria-hidden="true">&rarr;</span></a>{{/if}}</div>
</nav>
{{/with}}

/* ghostcn: Pagination */
.ghcn-pagination { box-sizing: border-box; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 1em; width: min(100% - 2em,72em); margin: 3em auto; color: var(--foreground); font-family: inherit; font-size: 16px; line-height: 1.5; isolation: isolate; }
.ghcn-pagination *, .ghcn-pagination *::before, .ghcn-pagination *::after { box-sizing: border-box; }
.ghcn-pagination__side { display: flex; }
.ghcn-pagination__side--end { justify-content: flex-end; }
.ghcn-pagination__status { color: var(--muted-foreground); font-size: 0.8125em; }
@media (max-width: 480px) { .ghcn-pagination { grid-template-columns: 1fr 1fr; } .ghcn-pagination__status { grid-column: 1 / -1; grid-row: 1; text-align: center; } }
